// SPDX-FileCopyrightText: 2026 Chili.CHIPS*ba
// SPDX-FileCopyrightText: 2026 Julian Kammerer
//
// SPDX-License-Identifier: GPL-3.0-or-later

// The primary dataflow for single clock domain ChaCha20-Poly1305 encryption
#pragma MAIN_MHZ encrypt_dataflow 80.0
void encrypt_dataflow(){
    // Connect chacha20poly1305_encrypt_* input stream to chacha20
    chacha20_encrypt_axis_in = chacha20poly1305_encrypt_axis_in;
    chacha20poly1305_encrypt_axis_in_ready = chacha20_encrypt_axis_in_ready;
    chacha20_encrypt_key = chacha20poly1305_encrypt_key;
    chacha20_encrypt_nonce = chacha20poly1305_encrypt_nonce;

    // Connect chacha20 output poly key into poly1305_mac key input
    poly1305_mac_encrypt_key = chacha20_encrypt_poly_key;
    chacha20_encrypt_poly_key_ready = poly1305_mac_encrypt_key_ready;

    // Connect chacha20 ciphertext output to both
    //  prep_auth_data input
    //  append auth tag input
    // Fork the stream by combining valids and readys
    //  default no data passing, invalidate passthrough
    prep_auth_data_encrypt_axis_in = chacha20_encrypt_axis_out;
    prep_auth_data_encrypt_axis_in.valid = 0;
    append_auth_tag_axis_in = chacha20_encrypt_axis_out;
    append_auth_tag_axis_in.valid = 0;
    //  allow pass through if both sinks are ready
    //  or if sink isnt ready (no data passing anyway)
    chacha20_encrypt_axis_out_ready = prep_auth_data_encrypt_axis_in_ready & append_auth_tag_axis_in_ready;
    if(chacha20_encrypt_axis_out_ready | ~prep_auth_data_encrypt_axis_in_ready){
        prep_auth_data_encrypt_axis_in.valid = chacha20_encrypt_axis_out.valid;
    }
    if(chacha20_encrypt_axis_out_ready | ~append_auth_tag_axis_in_ready){
        append_auth_tag_axis_in.valid = chacha20_encrypt_axis_out.valid;
    }

    // Prep auth data CSR inputs
    prep_auth_data_encrypt_aad = chacha20poly1305_encrypt_aad;
    prep_auth_data_encrypt_aad_len = chacha20poly1305_encrypt_aad_len;

    // Connect prep_auth_data output to poly1305_mac input
    poly1305_mac_encrypt_data_in = prep_auth_data_encrypt_axis_out;
    prep_auth_data_encrypt_axis_out_ready = poly1305_mac_encrypt_data_in_ready;

    // Connect poly1305_mac auth tag output to append auth tag input
    append_auth_tag_auth_tag_in = poly1305_mac_encrypt_auth_tag;
    poly1305_mac_encrypt_auth_tag_ready = append_auth_tag_auth_tag_in_ready;

    // Connect append auth tag output to chacha20poly1305_encrypt_* output
    chacha20poly1305_encrypt_axis_out = append_auth_tag_axis_out;
    append_auth_tag_axis_out_ready = chacha20poly1305_encrypt_axis_out_ready;
}

// SPDX-FileCopyrightText: 2026 Chili.CHIPS*ba
// SPDX-FileCopyrightText: 2026 Julian Kammerer
//
// SPDX-License-Identifier: GPL-3.0-or-later

#pragma once
#include "compiler.h"
#include "../chacha20/chacha20.h"
#include "../prep_auth_data/prep_auth_data.h"
#include "../poly1305/poly1305.h"

#ifndef SIMULATION
// Flattened top level ports with AXIS style manager/subordinate naming
// (could also have inputs and outputs of type stream(my_axis_t)
//  but ex. Verilog does not support VHDL arrays or records...)
// Top level input wires
DECL_INPUT(key_uint_t, encrypt_key)
DECL_INPUT(nonce_uint_t, encrypt_nonce)
DECL_INPUT(aad_uint_t, encrypt_aad)
DECL_INPUT(uint8_t, encrypt_aad_len)
// Top level input stream of plaintext
DECL_INPUT(uint128_t, encrypt_s_axis_tdata)
DECL_INPUT(uint16_t, encrypt_s_axis_tkeep)
DECL_INPUT(uint1_t, encrypt_s_axis_tlast)
DECL_INPUT(uint1_t, encrypt_s_axis_tvalid)
DECL_OUTPUT(uint1_t, encrypt_s_axis_tready)
// Top level output stream of ciphertext w/ auth tag
DECL_OUTPUT(uint128_t, encrypt_m_axis_tdata)
DECL_OUTPUT(uint16_t, encrypt_m_axis_tkeep)
DECL_OUTPUT(uint1_t, encrypt_m_axis_tlast)
DECL_OUTPUT(uint1_t, encrypt_m_axis_tvalid)
DECL_INPUT(uint1_t, encrypt_m_axis_tready)
#endif

// Nice struct/array type globally visible wires to use instead of flattened top level ports
// in simluation these wires are driven by the testbench
// in hardware these wires are driven by the top level ports
stream(axis128_t) chacha20poly1305_encrypt_axis_in; // input
uint1_t chacha20poly1305_encrypt_axis_in_ready; // output
uint8_t chacha20poly1305_encrypt_key[CHACHA20_KEY_SIZE]; // input
uint8_t chacha20poly1305_encrypt_nonce[CHACHA20_NONCE_SIZE]; // input
uint8_t chacha20poly1305_encrypt_aad[AAD_MAX_LEN]; // input
uint8_t chacha20poly1305_encrypt_aad_len; // input
stream(axis128_t) chacha20poly1305_encrypt_axis_out; // output
uint1_t chacha20poly1305_encrypt_axis_out_ready; // input

// For real hardware connect top level ports to these wires
#ifndef SIMULATION
#pragma MAIN chacha20poly1305_encrypt_io_wires
#pragma FUNC_WIRES chacha20poly1305_encrypt_io_wires
void chacha20poly1305_encrypt_io_wires(){
  // Convert flattened multiple input wires to stream(axis128_t)
  UINT_TO_BYTE_ARRAY(chacha20poly1305_encrypt_axis_in.data.tdata, 16, encrypt_s_axis_tdata)
  UINT_TO_BIT_ARRAY(chacha20poly1305_encrypt_axis_in.data.tkeep, 16, encrypt_s_axis_tkeep)
  chacha20poly1305_encrypt_axis_in.data.tlast = encrypt_s_axis_tlast;
  chacha20poly1305_encrypt_axis_in.valid = encrypt_s_axis_tvalid;
  encrypt_s_axis_tready = chacha20poly1305_encrypt_axis_in_ready;
  UINT_TO_BYTE_ARRAY(chacha20poly1305_encrypt_key, CHACHA20_KEY_SIZE, encrypt_key)
  UINT_TO_BYTE_ARRAY(chacha20poly1305_encrypt_nonce, CHACHA20_NONCE_SIZE, encrypt_nonce)
  UINT_TO_BYTE_ARRAY(chacha20poly1305_encrypt_aad, AAD_MAX_LEN, encrypt_aad)
  chacha20poly1305_encrypt_aad_len = encrypt_aad_len;
  // Convert stream(axis128_t) to flattened output multiple wires
  encrypt_m_axis_tdata = uint8_array16_le(chacha20poly1305_encrypt_axis_out.data.tdata);
  encrypt_m_axis_tkeep = uint1_array16_le(chacha20poly1305_encrypt_axis_out.data.tkeep);
  encrypt_m_axis_tlast = chacha20poly1305_encrypt_axis_out.data.tlast;
  encrypt_m_axis_tvalid = chacha20poly1305_encrypt_axis_out.valid;
  chacha20poly1305_encrypt_axis_out_ready = encrypt_m_axis_tready;
}
#endif

// SPDX-FileCopyrightText: 2026 Chili.CHIPS*ba
// SPDX-FileCopyrightText: 2026 Julian Kammerer
//
// SPDX-License-Identifier: GPL-3.0-or-later

// Instance of chacha20_loop_body
// requires data width converters to-from 512b wide blocks 128b bus
// use axis128/512 stream types
#include "axi/axis.h"
#include "global_func_inst.h"
#include "chacha20.h"
#include "../poly1305/poly1305.h"

#ifndef CHACHA_INST
#define CHACHA_INST chacha20
#endif

// Globally visible ports
// CSR inputs
uint8_t PPCAT(CHACHA_INST,_key)[CHACHA20_KEY_SIZE]; // input
uint8_t PPCAT(CHACHA_INST,_nonce)[CHACHA20_NONCE_SIZE]; // input
// Input plaintext
stream(axis128_t) PPCAT(CHACHA_INST,_axis_in); // input
uint1_t PPCAT(CHACHA_INST,_axis_in_ready); // output
// Output poly1305_key
stream(poly1305_key_uint_t) PPCAT(CHACHA_INST,_poly_key); // output
uint1_t PPCAT(CHACHA_INST,_poly_key_ready); // input
// Output ciphertext
stream(axis128_t) PPCAT(CHACHA_INST,_axis_out); // output
uint1_t PPCAT(CHACHA_INST,_axis_out_ready); // input

#ifndef CHACHA_EXCLUDES_PIPELINE
// Global instance of the chacha20_loop_body pipeline
GLOBAL_VALID_READY_PIPELINE_INST(PPCAT(CHACHA_INST,_pipeline), axis512_t, chacha20_loop_body, chacha20_loop_body_in_t, 64)
#endif

// Instance of FSM to control pipeline
MAIN(CHACHA_INST)
void CHACHA_INST(){
  chacha20_fsm_t fsm_out = chacha20_fsm(
    PPCAT(CHACHA_INST,_key),
    PPCAT(CHACHA_INST,_nonce),
    PPCAT(CHACHA_INST,_axis_in),
    PPCAT(CHACHA_INST,_poly_key_ready),
    PPCAT(CHACHA_INST,_axis_out_ready),
    PPCAT(CHACHA_INST,_pipeline_in_ready),
    PPCAT(CHACHA_INST,_pipeline_out)
  );
  PPCAT(CHACHA_INST,_axis_in_ready) = fsm_out.ready_for_axis_in;
  PPCAT(CHACHA_INST,_poly_key) = fsm_out.poly_key;
  PPCAT(CHACHA_INST,_axis_out) = fsm_out.axis;
  PPCAT(CHACHA_INST,_pipeline_in) = fsm_out.to_pipeline;
  PPCAT(CHACHA_INST,_pipeline_out_ready) = fsm_out.ready_for_from_pipeline;
}

#undef CHACHA_INST

