6	#pragma once
7	/**
8	 * based on code from
9	 * https://github.com/chili-chips-ba/wireguard-fpga/blob/main/2.sw/app/chacha20poly1305/chacha20.c
10	*/
11	
12	#include "intN_t.h"
13	#include "uintN_t.h"
14	#include "compiler.h"
15	#include "axi/axis.h"
16	#include "../poly1305/poly1305.h"
17	
18	#define CHACHA20_STATE_NWORDS 16
19	#define CHACHA20_KEY_SIZE 32
20	#define key_uint_t uint256_t
21	#define CHACHA20_NONCE_SIZE 12
22	#define nonce_uint_t uint96_t
23	#define CHACHA20_BLOCK_SIZE 64
24	
25	// ChaCha20 state structure
26	typedef struct chacha20_state
27	{
28	    uint32_t state[CHACHA20_STATE_NWORDS]; // ChaCha20 state (16 words)
29	} chacha20_state;
30	// TODO is byte order for above struct little endian / does it match type_bytes_t.h?
31	#include "chacha20_state_bytes_t.h" // PipelineC byte casting funcs
32	
33	// The ChaCha20 quarter round function
34	// TODO abcd are constants and might get better results if this function made into macro
35	chacha20_state quarter_round(chacha20_state s, uint4_t a, uint4_t b, uint4_t c, uint4_t d)
36	{
37	    chacha20_state o = s;
38	
39	    // decompose ops
40	    uint32_t a1 = o.state[a] + o.state[b];
41	    uint32_t d1 = rotl32_16(o.state[d] ^ a1);
42	    uint32_t c1 = o.state[c] + d1;
43	    uint32_t b1 = rotl32_12(o.state[b] ^ c1);
44	    uint32_t a2 = a1 + b1;
45	    uint32_t d2 = rotl32_8(d1 ^ a2);
46	    uint32_t c2 = c1 + d2;
47	    uint32_t b2 = rotl32_7(b1 ^ c2);
48	    
49	    // join output
50	    o.state[a] = a2;
51	    o.state[b] = b2;
52	    o.state[c] = c2;
53	    o.state[d] = d2;
54	
55	    return o;
56	}
57	
58	chacha20_state chacha20_block_step(chacha20_state state0){
59	    // make a giant pipeline with 8 parallel ops
60	    chacha20_state state1 = quarter_round(state0, 0, 4, 8, 12);
61	    chacha20_state state2 = quarter_round(state1, 1, 5, 9, 13);
62	    chacha20_state state3 = quarter_round(state2, 2, 6, 10, 14);
63	    chacha20_state state4 = quarter_round(state3, 3, 7, 11, 15);
64	    chacha20_state state5 = quarter_round(state4, 0, 5, 10, 15);
65	    chacha20_state state6 = quarter_round(state5, 1, 6, 11, 12);
66	    chacha20_state state7 = quarter_round(state6, 2, 7, 8, 13);
67	    chacha20_state state8 = quarter_round(state7, 3, 4, 9, 14);
68	    return state8;
69	}
70	
71	// ChaCha20 block function pipeline
72	chacha20_state chacha20_block(chacha20_state state)
73	{
74	    chacha20_state output;
75	
76	    // 1. do 20 steps (2x each step) (giant pipeline)
77	    // TODO could be loop?
78	    chacha20_state step1  = chacha20_block_step(state);
79	    chacha20_state step2  = chacha20_block_step(step1);
80	    chacha20_state step3  = chacha20_block_step(step2);
81	    chacha20_state step4  = chacha20_block_step(step3);
82	    chacha20_state step5  = chacha20_block_step(step4);
83	    chacha20_state step6  = chacha20_block_step(step5);
84	    chacha20_state step7  = chacha20_block_step(step6);
85	    chacha20_state step8  = chacha20_block_step(step7);
86	    chacha20_state step9  = chacha20_block_step(step8);
87	    chacha20_state step10 = chacha20_block_step(step9);
88	    
89	    // 2. final parallel add
90	    uint4_t i;
91	    for (i = 0; i < CHACHA20_STATE_NWORDS; i+=1)
92	    {
93	        output.state[i] = step10.state[i] + state.state[i];
94	    }
95	
96	    return output;
97	}
98	
99	
100	// ChaCha20 initialization function
101	chacha20_state chacha20_init(
102	  uint8_t key[CHACHA20_KEY_SIZE], 
103	  uint8_t nonce[CHACHA20_NONCE_SIZE], 
104	  uint32_t counter
105	){
106	    chacha20_state state;
107	    // Set the initial state (constants + key + nonce)
108	    // "expand 32-byte k"
109	    state.state[0] = 0x61707865; // "apxe"
110	    state.state[1] = 0x3320646e; // "3 dn"
111	    state.state[2] = 0x79622d32; // "yb-2"
112	    state.state[3] = 0x6b206574; // "k et"
113	
114	    // Key
115	    uint32_t key_as_u32s[CHACHA20_KEY_SIZE/4];
116	    for(uint32_t i = 0; i < CHACHA20_KEY_SIZE/4; i+=1)
117	    {
118	      uint16_t lsbs = uint8_uint8(key[(i*4)+1], key[(i*4)+0]);
119	      uint16_t msbs = uint8_uint8(key[(i*4)+3], key[(i*4)+2]);
120	      key_as_u32s[i] = uint16_uint16(msbs, lsbs);
121	    }
122	    for(uint32_t i = 0; i < CHACHA20_KEY_SIZE/4; i+=1)
123	    {
124	        state.state[4 + i] = key_as_u32s[i];
125	    }
126	
127	    // Counter
128	    state.state[12] = counter;
129	
130	    // Nonce
131	    uint32_t nonce_as_u32s[CHACHA20_NONCE_SIZE/4];
132	    for(uint32_t i = 0; i < CHACHA20_NONCE_SIZE/4; i+=1)
133	    {
134	      uint16_t lsbs = uint8_uint8(nonce[(i*4)+1], nonce[(i*4)+0]);
135	      uint16_t msbs = uint8_uint8(nonce[(i*4)+3], nonce[(i*4)+2]);
136	      nonce_as_u32s[i] = uint16_uint16(msbs, lsbs);
137	    }
138	    for(uint32_t i = 0; i < CHACHA20_NONCE_SIZE/4; i+=1)
139	    {
140	        state.state[13 + i] = nonce_as_u32s[i];
141	    }
142	
143	    return state;
144	}
145	
146	/* Original software C
147	// ChaCha20 encryption/decryption function
148	void chacha20_encrypt(uint8_t *out, const uint8_t *in, size_t length, const uint8_t *key, const uint8_t *nonce, uint32_t counter)
149	{
150	    chacha20_state state;
151	    chacha20_state block;
152	    uint8_t *block_bytes = (uint8_t *)(block.state);
153	
154	    while (length > 0)
155	    {
156	        chacha20_init(&state, key, nonce, counter);
157	        chacha20_block(&state, &block);
158	
159	        size_t chunk_size = length > 64 ? 64 : length;
160	        for (size_t i = 0; i < chunk_size; i++)
161	        {
162	            out[i] = in[i] ^ block_bytes[i];
163	        }
164	
165	        counter++;
166	        length -= chunk_size;
167	        out += chunk_size;
168	        in += chunk_size;
169	    }
170	}
171	// Pseudo code version of above chacha20_encrypt using fixed size arrays and no pointers
172	uint8_t[64] chacha20_encrypt_fixed(
173	  uint8_t in[64], 
174	  size_t length, 
175	  uint32_t key[32], 
176	  uint32_t nonce[12], 
177	  uint32_t counter
178	){
179	  chacha20_state state;
180	  chacha20_state block;
181	  uint8_t out[64];
182	  int pos = 0;
